    "imageUrl": "https://imagens.ebc.com.br/PQ1HVYFITdqyRj35BA2RGViLdsI=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2025/03/27/eukathlen.jpg?itok=nwdxRNUB",
