    "category": "Justiça",
    "ingestedAt": "25/11/2026 às 15:59",
    "imageUrl": "https://imagens.ebc.com.br/0q3-lomWLRsvoTT7z2lAGaigkb0=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2025/04/28/hurb.jpg?itok=iPi4Tn_R",
